import Foundation

/// `Documentation/Foundations/TOKEN_COVERAGE.md`: which upstream tokens iOS generates, which it does
/// not and why, and which colours needed Display P3 or gamut mapping. Generated, so it cannot drift.
struct CoverageReport {
    let model: TokenModel
    let provenance: Provenance

    func markdown() -> String {
        var lines: [String] = [
            "<!-- GENERATED by qeetrix-gen — do not edit. Run Scripts/generate.sh. -->",
            "",
            "# Token coverage",
            "",
            "Source: `\(provenance.qeetrixUIPackage)@\(provenance.qeetrixUIVersion)` (git `\(provenance.qeetrixUIGitHead.prefix(7))`), themes \(model.themes.map { "`\($0)`" }.joined(separator: ", ")).",
            "",
            "\(model.included.count) tokens are generated as Swift; \(model.excluded.count) are not. The rule is in",
            "[`Scripts/Sources/QeetrixGenCore/Tokens/Scope.swift`](../../Scripts/Sources/QeetrixGenCore/Tokens/Scope.swift).",
            "",
            "## Generated",
            "",
            "| Group | Tokens | Swift |",
            "|:--|--:|:--|",
        ]
        let groups: [([String], String)] = [
            (["color"], "`QeetrixColor`"),
            (["elevation"], "`QeetrixElevation`"),
            (["typography"], "`QeetrixTextRole`"),
            (["font", "weight"], "`QeetrixFontWeight`"),
            (["font", "geometry"], "`QeetrixFontGeometry`"),
            (["space"], "`QeetrixSpacing`"),
            (["corner"], "`QeetrixCorner`"),
            (["stroke", "width"], "`QeetrixStroke`"),
            (["focus"], "`QeetrixFocus`"),
            (["state", "opacity"], "`QeetrixOpacity`"),
            (["icon", "size"], "`QeetrixIconSize`"),
            (["icon", "stroke"], "`QeetrixIconStroke`"),
            (["density"], "`QeetrixDensity`"),
            (["motion"], "`QeetrixDuration`, `QeetrixEasing`, `QeetrixMotion`"),
        ]
        var counted = 0
        for (prefix, swift) in groups {
            let count = model.tokens(under: prefix).count
            counted += count
            lines.append("| `\(prefix.joined(separator: "."))` | \(count) | \(swift) |")
        }
        lines.append("")
        if counted != model.included.count {
            lines.append("> \(model.included.count - counted) generated tokens are not listed above — update CoverageReport.swift.")
            lines.append("")
        }

        lines += ["## Not generated", "", "| Reason | Tokens | Examples |", "|:--|--:|:--|"]
        var reasons: [String] = []
        var byReason: [String: [ExcludedToken]] = [:]
        for token in model.excluded {
            if byReason[token.reason] == nil { reasons.append(token.reason) }
            byReason[token.reason, default: []].append(token)
        }
        for reason in reasons {
            let tokens = byReason[reason]!
            let examples = tokens.prefix(3).map { "`\($0.path.joined(separator: "."))`" }.joined(separator: ", ")
            lines.append("| \(reason) | \(tokens.count) | \(examples)\(tokens.count > 3 ? ", …" : "") |")
        }
        lines.append("")

        lines += ["## Colours outside sRGB", ""]
        var wide: [String] = []
        for token in model.tokens(under: ["color"]) {
            for theme in model.themes {
                if case let .color(color)? = token.values[theme], color.space == .displayP3 {
                    wide.append(
                        "| `\(token.dotted)` | \(theme) | \(color.gamutMapped ? "outside P3 — gamut-mapped (CSS Color 4)" : "inside P3 — drawn in Display P3") |"
                    )
                }
            }
        }
        if wide.isEmpty {
            lines.append("None: every semantic colour converts into sRGB, so each matches its web hex value exactly.")
        } else {
            lines +=
                [
                    "These convert outside sRGB. They are emitted in Display P3, which is how Safari paints them on an iPhone.",
                    "",
                    "| Token | Theme | Handling |",
                    "|:--|:--|:--|",
                ] + wide
        }
        lines.append("")
        return lines.joined(separator: "\n")
    }
}
